import{connectedTerrain}from'./terrain.js';import{mapFingerprint}from'./world-decor.js';
// A continuous sandwich surface following the authored opaque runs, not tile UVs.
export function banquetSource(assets,level,map){const width=4096,height=level.height*16,source=new Uint8Array(width*height),tops=new Int16Array(source.length).fill(-1),bottoms=new Int16Array(source.length).fill(-1);
 for(let ty=0;ty<level.height;ty++)for(let tx=0;tx<256;tx++){const v=level.lookup[map[ty*256+tx]];if(v===undefined||v===256||v===65535)continue;const bank=v<256?assets.tiles[level.id]:assets.union,off=(v<256?v:v-256)*256;for(let y=0;y<16;y++)source.set(bank.subarray(off+y*16,off+y*16+16),(ty*16+y)*width+tx*16);}
 for(let x=0;x<width;x++){let y=0;while(y<height){if(!source[y*width+x]){y++;continue;}const top=y;while(y<height&&source[y*width+x])y++;for(let yy=top;yy<y;yy++){const p=yy*width+x;tops[p]=top;bottoms[p]=y-1;}}}return{width,height,source,tops,bottoms};}
export function banquetSampler(world,material,ox,oy){const out=new Float32Array(4);return(x,y)=>{const wx=ox*4+x,wy=oy*4+y,nx=Math.max(0,Math.min(world.width-1,Math.floor(wx/4))),ny=Math.max(0,Math.min(world.height-1,Math.floor(wy/4))),p=ny*world.width+nx,top=world.tops[p],bottom=world.bottoms[p];if(top<0){out.fill(0);return out;}const u=((wx%material.width)+material.width)%material.width,v=Math.max(0,Math.min(material.height-1,Math.floor((wy/4-top+.5)/(bottom-top+1)*material.height))),q=(v*material.width+Math.floor(u))*4;for(let k=0;k<3;k++)out[k]=material.data[q+k];out[3]=1;return out;};}
export class BanquetTerrain{
 constructor(){this.chunks=new Map();}
 draw(hd,assets,level,map,cx,cy){const fingerprint=mapFingerprint(map);if(this.map!==map||this.fingerprint!==fingerprint){this.map=map;this.fingerprint=fingerprint;this.world=banquetSource(assets,level,map);this.chunks.clear();}const w=this.world,material=hd.materialImage(hd.pack.manifest.banquetMaterial),size=64,halo=16,extent=96;
 hd.clipped(176,c=>{for(let gy=Math.max(0,Math.floor(cy/size));gy<=Math.floor((cy+175)/size);gy++)for(let gx=Math.max(0,Math.floor(cx/size));gx<=Math.floor((cx+319)/size);gx++){const key=gx+':'+gy,ox=gx*size,oy=gy*size;let image=this.chunks.get(key);if(!image){const src=new Uint8Array(extent*extent);for(let y=0;y<extent;y++)for(let x=0;x<extent;x++){const wx=ox+x-halo,wy=oy+y-halo;if(wx>=0&&wx<w.width&&wy>=0&&wy<w.height)src[y*extent+x]=w.source[wy*w.width+wx];}const rgba=connectedTerrain(src,extent,extent,hd.palette,banquetSampler(w,material,ox-halo,oy-halo),{paintColor:true});image=document.createElement('canvas');image.width=image.height=256;image.getContext('2d').putImageData(new ImageData(rgba,384,384),-64,-64);this.chunks.set(key,image);}c.drawImage(image,(ox-cx)*4,(oy-cy)*4);}});while(this.chunks.size>96)this.chunks.delete(this.chunks.keys().next().value);return true;
 }
}
